public sealed class ReminderWorker(IReminderStore store, ILogger<ReminderWorker> logger) : BackgroundService
{
    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        using var timer = new PeriodicTimer(TimeSpan.FromSeconds(30));
        while (await timer.WaitForNextTickAsync(stoppingToken))
        {
            var due = await store.GetDueAsync(DateTimeOffset.UtcNow, stoppingToken);
            foreach (var reminder in due)
            {
                logger.LogInformation("Sending reminder {Id} to {User}", reminder.Id, reminder.UserId);
                await store.MarkSentAsync(reminder.Id, stoppingToken);
            }
        }
    }
}

