@dataclass
class Document:
    doc_id: str
    title: str
    body: str
    tags: list[str] = field(default_factory=list)


class InvertedIndex:
    def __init__(self) -> None:
        self._postings: dict[str, set[str]] = {}

    def add(self, doc: Document) -> None:
        for token in set(f"{doc.title} {doc.body}".lower().split()):
            self._postings.setdefault(token, set()).add(doc.doc_id)

    def search(self, query: str) -> set[str]:
        sets = [self._postings.get(t, set()) for t in query.lower().split()]
        return set.intersection(*sets) if sets else set()

    def dump(self, path: Path) -> None:
        payload = {k: sorted(v) for k, v in self._postings.items()}
        path.write_text(json.dumps(payload))

