  private readonly log = new Logger(VelocityCheck.name);

  constructor(private readonly redis: Redis) {}

  async evaluate(transfer: Transfer): Promise<RiskVerdict> {
    const key = `velocity:${transfer.accountId}`;
    const count = await this.redis.incr(key);
    if (count === 1) {
      await this.redis.expire(key, 600);
    }

    if (count > 8) {
